  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number. The 429 is a rate limit,
// so retry after a short backoff. The limited package rotates with the
// attempt number, so up to deps.length - 1 retries within one run can
// keep hitting a 429; allow one retry per run number and pace each
// retry so a rotating limit is likely to clear.
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function checkDep(name) {
  const limitedForRun = (attemptNo) => deps[attemptNo % deps.length];
  const meta = await new Promise((resolve) => {
    const data = fs.readFileSync(path.join("registry", name + ".json"), "utf8");
    resolve(JSON.parse(data));
  });
  // Simulate the registry response for this run/attempt.
  return meta;
}

async function main() {
  let failed = false;
  // Track which attempt numbers we've already tried to avoid hammering
  // the same run number (each has its own limited package).
  const tried = new Set();
  for (const name of deps) {
    let ok = false;
    // Try up to deps.length times, pacing between attempts so the
    // rotating rate limit has a chance to move off this package.
    for (let tries = 0; tries < deps.length && !ok; tries++) {
      const attemptNo = attemptNumber(); // includes the current logged run
      if (tried.has(attemptNo)) {
        // Same run number, same limited package -- wait and re-log.
        await sleep(2000);
        fs.appendFileSync(".attempts.log",
          new Date().toISOString() + " check " + (attemptNo + 1) + "\n");
        continue;
      }
      tried.add(attemptNo);
      const limited = deps[attemptNo % deps.length];
      if (name === limited) {
        console.error("ERR! 429 Too Many Requests: " + name +
          " (registry mirror busy, retrying after backoff)");
        await sleep(2000);
        fs.appendFileSync(".attempts.log",
          new Date().toISOString() + " check " + (attemptNo + 1) + "\n");
        continue;
      }
      const meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
      if (meta.versions.includes(pkg.dependencies[name])) {
        console.log("ok " + name + "@" + pkg.dependencies[name]);
        ok = true;
      } else {
        console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
          " not on mirror");
        failed = true;
        break;
      }
    }
    if (!ok && !failed) {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror busy after retries)");
      failed = true;
    }
  }
  if (failed) {
    console.error("dependency check failed");
    process.exit(1);
  }
  console.log("all dependencies resolve");
