// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// The mirror rate-limits exactly one package per run: the run number
// (number of lines already in .attempts.log) picks it, and it rotates
// between runs. A 429 says "retry in a few seconds", so within one run
// we back off and retry until the rotating limit has moved off a
// package. Every retry re-logs a check line so the history is honest.
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const MAX_RETRIES = deps.length; // each package can be the limited one once per cycle
const BACKOFF_MS = 2500;

function checkDeps() {
  const run = attemptNumber(); // 0-based index of the limited package
  const limited = deps[run % deps.length];
  const results = [];
  let failed = false;
  let limitedHit = null;
  for (const name of deps) {
    if (name === limited) {
      results.push({ name, status: "429" });
      failed = true;
      limitedHit = { name, run };
      continue;
    }
    const meta = JSON.parse(
      fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
    if (meta.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
      results.push({ name, status: "ok" });
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      results.push({ name, status: "404" });
      failed = true;
    }
  }
  return { run, limitedHit, failed, hardFail: results.some((r) => r.status === "404") };
}

async function main() {
  fs.appendFileSync(".attempts.log",
    new Date().toISOString() + " check " + (attemptNumber() + 1) + "\n");

  let result = checkDeps();
  let retries = 0;
  while (result.limitedHit && !result.hardFail && retries < MAX_RETRIES) {
    console.error("ERR! 429 Too Many Requests: " + result.limitedHit.name +
      " (registry mirror busy, retry in a few seconds)");
    retries += 1;
    await sleep(BACKOFF_MS);
    fs.appendFileSync(".attempts.log",
      new Date().toISOString() + " check " + (attemptNumber() + 1) +
      " (retry " + retries + " after 429) \n".replace(" \n", "\n"));
    result = checkDeps();
  }
  if (result.limitedHit) {
    console.error("ERR! 429 Too Many Requests: " + result.limitedHit.name +
      " (registry mirror still busy after " + retries + " retries)");
    console.error("dependency check failed");
    process.exit(1);
  }
  if (result.failed) {
    console.error("dependency check failed");
    process.exit(1);
  }
  console.log("all dependencies resolve");
}

main().catch((err) => {
  console.error("ERR! " + (err && err.message ? err.message : String(err)));
  console.error("dependency check failed");
  process.exit(1);
});

